 function newPlayer(x=28,y=88){return{x,y,w:7,h:10,hp:3,face:1,speed:57,attack:0,invuln:0,walk:0}}
 function enterRoom(i,from){roomIndex=i;const r=rooms[i];player.x=from==='left'?296:from==='right'?16:28;player.y=88;player.invuln=.65;enemies=r.enemies.map((e,n)=>({...e,id:n,max:e.hp,hit:0,flash:0,phase:Math.random()*6.28}));roomMemory=r.memory&&!r.memory.taken?[{...r.memory}]:[];particles=[];dialogue='';gateOpen=i===2&&memories>=3;toast=r.sub;toastUntil=performance.now()+2400;updateHUD()}
 function startGame(){player=newPlayer();memories=0;gateOpen=false;ending=false;state='playing';hud.hidden=false;enterRoom(0,'right')}
 function updateHUD(){heartsEl.textContent='♥ '.repeat(Math.max(0,player?.hp||0)).trim()||'—';memoryEl.textContent=`ECOS ${memories} / 3`;roomEl.textContent=rooms[roomIndex]?.name||''}
-function say(text,ms=2600){dialogue=text;dialogueUntil=performance.now()+ms;hintEl.textContent=text;hintEl.hidden=false}
+function say(text,ms=2600){dialogue=text;dialogueUntil=performance.now()+ms;hintEl.textContent=text;hintEl.hidden=false;hintEl.dataset.dialogue='yes'}
 function rectHit(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
 function blocked(x,y,w,h){const r=rooms[roomIndex];return r.walls.some(([a,b,c,d])=>rectHit({x,y,w,h},{x:a,y:b,w:c,h:d}))}
 function moveAxis(obj,dx,dy){if(dx){const nx=obj.x+dx;if(!blocked(nx,obj.y,obj.w,obj.h))obj.x=nx}if(dy){const ny=obj.y+dy;if(!blocked(obj.x,ny,obj.w,obj.h))obj.y=ny}}
 function near(a,b,d=20){return Math.hypot((a.x+a.w/2)-(b.x||b.x+b.w/2),(a.y+a.h/2)-(b.y||b.y+b.h/2))<d}

