 if(player.attack>0){ctx.save();ctx.globalAlpha=Math.min(1,player.attack*5);ctx.fillStyle='#f6d79d';ctx.fillRect(x+(player.face>0?8:-10),y+2,9,2);ctx.fillRect(x+(player.face>0?12:-12),y+4,3,7);ctx.fillStyle='#fff0c8';ctx.fillRect(x+(player.face>0?10:-8),y+5,5,1);ctx.restore()}}
function drawParticles(){for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(Math.round(p.x),Math.round(p.y),2,2)}ctx.globalAlpha=1}
