 ctx.fillStyle='#080a10b8';ctx.fillRect(0,0,W,H);ctx.fillStyle='#d8b576';ctx.beginPath();ctx.arc(160,55,26,0,Math.PI*2);ctx.fill();ctx.fillStyle='#131720';ctx.beginPath();ctx.arc(167,49,22,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e8dfca';ctx.font='bold 22px monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('ECLIPSE',160,88);ctx.fillStyle='#c6a575';ctx.font='8px monospace';ctx.fillText('CINZAS DO AMANHÃ',160,103);ctx.fillStyle='#c0b9ad';ctx.font='7px monospace';ctx.fillText('Um eco. Uma lâmina. O que resta de você.',160,120);ctx.fillStyle='#fff0cb';ctx.fillText('PRESSIONE ENTER / TOQUE PARA COMEÇAR',160,147);ctx.fillStyle='#777981';ctx.fillText('WASD / SETAS mover   •   ESPAÇO atacar   •   E interagir',160,162);
 }else if(state==='dead'||state==='won'){
